mapper.select:
select t.id, t.merchant_id, t.name, t.scope_type, t.owner_store_id, t.source_template_id, t.status, t.cloned_from_theme_id, t.cloned_from_version_id, t.updated_at, v.version_no latest_version_no, d.revision draft_revision, case when exists ( select 1 from store_theme_bindings active_binding where active_binding.merchant_id = t.merchant_id and active_binding.theme_id = t.id and active_binding.store_id = #{scopeId} and active_binding.mode = 'FOLLOW_MERCHANT' ) then 1 else 0 end is_active, case when d.id is null then 0 when v.id is null then 1 when d.config_json = v.config_json then 0 else 1 end has_unpublished_changes from themes t left join theme_drafts d on d.merchant_id = t.merchant_id and d.theme_id = t.id left join theme_versions v on v.id = ( select latest.id from theme_versions latest where latest.merchant_id = t.merchant_id and latest.theme_id = t.id order by latest.version_no desc limit 1 ) where t.merchant_id = #{merchantId} and t.status = 'ACTIVE' and t.scope_type = #{scopeType}
and t.owner_store_id = #{scopeId} and t.owner_store_id is null
order by is_active desc, t.updated_at desc, t.id desc

select coalesce(max(version_no), 0) + 1
from theme_versions
where merchant_id = #{merchantId} and theme_id = #{themeId}

select count(distinct id) from assets where id in
#{assetId}
and status = 'ACTIVE' and audit_status = 'APPROVED' and (scope_type = 'SYSTEM' or (scope_type = 'MERCHANT' and merchant_id = #{merchantId}))
